    fun setUserLocation(lngLat: Pair<Double, Double>?, options: MapUserLocationOptions?, reply: Reply<Unit, UIMapNodeCode>)

    // ---- what the holder (UINodeHost) hands the instance, by name: read by the contract here — the
    // plugin implements none of it ----
    override fun setProperty(name: String, value: String?) = UIMapNodeGlue.setProperty(this, name, value)
    override fun setStyle(name: String, color: Int?) {}
    override fun setStyle(name: String, number: Double?) {}
    /** Never asked: the node's styles size it. */
    override fun measure(c: HostNodeConstraints): SizeF = SizeF(0f, 0f)
    override fun call(method: String, r: PackedReader, settle: ChannelSettle) = UIMapNodeGlue.call(this, method, r, settle)
    /** The holder paints the whole box. */
    override val paintsSelf: Boolean get() = false
}

/** The host node "map": its registration, and the glue between the holder and the instance. */
object UIMapNodeGlue {
    /** What the halves register under: the node's kind. */
    const val NAME = "map"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 1

    /** Register the node: `make` builds one instance per node of the kind, when the SDK creates one. */
    fun register(engine: LecodesEngine, make: (events: UIMapNodeEvents) -> UIMapNodeInstance) {
        engine.registerNode(NAME, VERSION) { channel -> make(UIMapNodeEvents(channel)) }
    }

    /** A prop the SDK wrote: its text, null when it was cleared. */
    internal fun setProperty(i: UIMapNodeInstance, name: String, value: String?) {
        when (name) {
            "styleUrl" -> i.setStyleUrl(value)
            "styleJson" -> i.setStyleJson(value)
            "center" -> {
                i.setCenter(if (value == null) null else json(value) { r -> r.tuple(2) {
                    val v0_0 = r.f64() ?: return@tuple null
                    val v0_1 = r.f64() ?: return@tuple null
                    Pair(v0_0, v0_1)
                } } ?: return dropped(name))
            }
            "zoom" -> i.setZoom(if (value == null) null else value.toDoubleOrNull() ?: return dropped(name))
            "minZoom" -> i.setMinZoom(if (value == null) null else value.toDoubleOrNull() ?: return dropped(name))
            "maxZoom" -> i.setMaxZoom(if (value == null) null else value.toDoubleOrNull() ?: return dropped(name))
            "bearing" -> i.setBearing(if (value == null) null else value.toDoubleOrNull() ?: return dropped(name))
            "pitch" -> i.setPitch(if (value == null) null else value.toDoubleOrNull() ?: return dropped(name))
            "rotate" -> i.setRotate(if (value == null) null else bool(value) ?: return dropped(name))
            "tilt" -> i.setTilt(if (value == null) null else bool(value) ?: return dropped(name))
            else -> {}   // `kind` (the holder's), or a prop of a newer contract
        }
    }

    /** A call of the SDK: read off the wire and handed to the instance; a malformed call never reaches it. */
    internal fun call(i: UIMapNodeInstance, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "ensureLayer" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — UIMap.ensureLayer: source")
                val a1 = (if (1 < n) MapLayerKind.read(r) else null) ?: return settle.reject("bad arguments — UIMap.ensureLayer: kind")
                val a2 = if (2 < n && !r.isNull()) (MapLayerOptions.read(r) ?: return settle.reject("bad arguments — UIMap.ensureLayer: options")) else { if (2 < n) r.skip(); null }
                i.ensureLayer(a0, a1, a2, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "removeLayer" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — UIMap.removeLayer: source")
                i.removeLayer(a0, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "setData" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — UIMap.setData: source")
                val a1 = (if (1 < n) r.json() else null) ?: return settle.reject("bad arguments — UIMap.setData: geojson")
                i.setData(a0, a1, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "flyTo" -> {
                val a0 = (if (0 < n) r.tuple(2) {
                    val v0_0 = r.f64() ?: return@tuple null
                    val v0_1 = r.f64() ?: return@tuple null
                    Pair(v0_0, v0_1)
                } else null) ?: return settle.reject("bad arguments — UIMap.flyTo: center")
                val a1 = if (1 < n && !r.isNull()) (MapCameraMove.read(r) ?: return settle.reject("bad arguments — UIMap.flyTo: options")) else { if (1 < n) r.skip(); null }
                i.flyTo(a0, a1, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "jumpTo" -> {
                val a0 = (if (0 < n) r.tuple(2) {
                    val v0_0 = r.f64() ?: return@tuple null
                    val v0_1 = r.f64() ?: return@tuple null
                    Pair(v0_0, v0_1)
                } else null) ?: return settle.reject("bad arguments — UIMap.jumpTo: center")
                val a1 = if (1 < n && !r.isNull()) (MapCameraMove.read(r) ?: return settle.reject("bad arguments — UIMap.jumpTo: options")) else { if (1 < n) r.skip(); null }
                i.jumpTo(a0, a1, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "fitPoints" -> {
                val a0 = (if (0 < n) r.list {
                    r.tuple(2) {
                        val v1_0 = r.f64() ?: return@tuple null
                        val v1_1 = r.f64() ?: return@tuple null
                        Pair(v1_0, v1_1)
                    }
                } else null) ?: return settle.reject("bad arguments — UIMap.fitPoints: points")
                val a1 = if (1 < n && !r.isNull()) (MapFitOptions.read(r) ?: return settle.reject("bad arguments — UIMap.fitPoints: options")) else { if (1 < n) r.skip(); null }
                i.fitPoints(a0, a1, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "setPadding" -> {
                val a0 = (if (0 < n) MapPadding.read(r) else null) ?: return settle.reject("bad arguments — UIMap.setPadding: padding")
                i.setPadding(a0, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            "getCamera" -> {
                i.getCamera(Reply<MapCamera, UIMapNodeCode>(settle) { v, w -> v.write(w) })
            }
            "setUserLocation" -> {
                val a0 = if (0 < n && !r.isNull()) (r.tuple(2) {
                    val v0_0 = r.f64() ?: return@tuple null
                    val v0_1 = r.f64() ?: return@tuple null
                    Pair(v0_0, v0_1)
                } ?: return settle.reject("bad arguments — UIMap.setUserLocation: lngLat")) else { if (0 < n) r.skip(); null }
                val a1 = if (1 < n && !r.isNull()) (MapUserLocationOptions.read(r) ?: return settle.reject("bad arguments — UIMap.setUserLocation: options")) else { if (1 < n) r.skip(); null }
                i.setUserLocation(a0, a1, Reply<Unit, UIMapNodeCode>(settle, null))
            }
            else -> settle.reject("Unknown method: $method")
        }
    }

    private fun bool(text: String?): Boolean? = when (text) { "1" -> true; "0" -> false; else -> null }

    /** A prop's JSON text, read as the contract's type: null when it is not JSON, or not that type. */
    private fun <T> json(text: String, read: (PackedReader) -> T?): T? {
        val value = try { org.json.JSONTokener(text).nextValue() } catch (e: org.json.JSONException) { return null }
        return read(Wire.reader(value))
    }

    private fun dropped(prop: String) {
        android.util.Log.w("LeCodes", "the node \"$NAME\" dropped a value of $prop its contract does not read")
    }
}
